package uz.anncorp.smeta.core.ui

/*
 * ONE design source for the site, Android and Windows: design/tokens.json (-> DesignTokens.kt, generated by scripts/gen-design-tokens.mjs).
 * Values are plain ARGB longs so :shared stays Compose-free; QuraiTheme maps them 1:1 to the Material colour scheme.
 * This file only keeps the stable names used across the apps; do NOT hard-code a colour or size here, change design/tokens.json.
 */
data class QuraiPalette(
    val bg: Long, val surface: Long, val surface2: Long, val surface3: Long, val border: Long, val borderStrong: Long,
    val text: Long, val textDim: Long, val textMute: Long,
    val accent: Long, val accentText: Long, val onAccent: Long, val accentSoft: Long,
    val info: Long, val ok: Long, val warn: Long, val danger: Long, val dangerSoft: Long,
    val okSoft: Long, val warnSoft: Long, val infoSoft: Long,
    val katChel: Long, val katMash: Long, val katMat: Long, val katOb: Long,
)

object QuraiTokens {
    /** Dark theme (web default, `:root`). */
    val dark: QuraiPalette get() = DesignTokens.dark

    /** Light theme (web `data-mavzu="ganch"`). */
    val light: QuraiPalette get() = DesignTokens.light

    /** Brand mark (favicon.svg): navy tile, white Q, gold tail. */
    const val BRAND_NAVY = DesignTokens.BRAND_NAVY
    const val BRAND_GOLD = DesignTokens.BRAND_GOLD

    // Radii (dp), spacing (dp), control heights (dp), layout (dp): web --radius-*, --space-*, --control-*, --sidebar-*.
    const val RADIUS_XS = DesignTokens.RADIUS_XS; const val RADIUS_SM = DesignTokens.RADIUS_SM; const val RADIUS_MD = DesignTokens.RADIUS_MD; const val RADIUS_LG = DesignTokens.RADIUS_LG
    const val SPACE_1 = DesignTokens.SPACE_1; const val SPACE_2 = DesignTokens.SPACE_2; const val SPACE_3 = DesignTokens.SPACE_3; const val SPACE_4 = DesignTokens.SPACE_4
    const val SPACE_5 = DesignTokens.SPACE_5; const val SPACE_6 = DesignTokens.SPACE_6; const val SPACE_8 = DesignTokens.SPACE_8
    const val CONTROL_SM = DesignTokens.CONTROL_SM; const val CONTROL_MD = DesignTokens.CONTROL_MD; const val CONTROL_LG = DesignTokens.CONTROL_LG
    /** Android touch target (accessibility minimum, used for every tappable control on the phone). */
    const val TOUCH_TARGET = DesignTokens.CONTROL_TOUCH
    const val ROW_DENSE = DesignTokens.ROW_DENSE; const val ROW_COMFORT = DesignTokens.ROW_COMFORT
    const val SIDEBAR_RAIL = DesignTokens.SIDEBAR_RAIL; const val SIDEBAR_OPEN = DesignTokens.SIDEBAR_OPEN
    const val FONT_SANS = DesignTokens.FONT_SANS; const val FONT_MONO = DesignTokens.FONT_MONO
}
